const sampleData=RotationCore.comparison();const defaults={diskMass:6e10,diskA:3,diskB:.3,haloScaleMass:8e11,haloRadius:20,radius:8},state={...defaults},controls=[['diskMass','Disk mass (10¹⁰ solar masses)',0,15,.5,1e10],['diskA','Disk radial scale a (kpc)',0,10,.25,1],['diskB','Disk vertical scale b (kpc)',.1,2,.1,1],['haloScaleMass','Halo scale mass (10¹¹ solar masses)',0,20,.5,1e11],['haloRadius','Halo scale radius (kpc)',5,50,1,1],['radius','Inspect radius (kpc)',0,40,.25,1]],NS='http://www.w3.org/2000/svg',plot=document.getElementById('plot');
function node(tag,attrs,text){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;plot.append(e);return e;}
for(const[key,title,min,max,step,gain]of controls){const label=document.createElement('label');label.textContent=title+' ';const input=document.createElement('input');Object.assign(input,{id:key,type:'number',min,max,step,value:state[key]/gain});input.setAttribute('aria-label',title);input.onchange=()=>{const value=input.valueAsNumber;if(!Number.isFinite(value)||value<min||value>max){input.value=state[key]/gain;return;}state[key]=value*gain;render();};label.append(input);document.getElementById('controls').append(label);}
function render(){const rows=Array.from({length:161},(_,i)=>RotationCore.model(i/4,state)),maximum=Math.max(50,Math.ceil(Math.max(...rows.map(r=>r.totalSpeedKms),RotationCore.model(state.radius,state).totalSpeedKms,...sampleData.map(d=>d.speedKms+d.sigmaKms))/50)*50),X=r=>70+660*r/40,Y=v=>370-320*v/maximum;plot.replaceChildren();for(let i=0;i<=4;i++){const radius=i*10,y=maximum*i/4;node('line',{x1:70,y1:Y(y),x2:730,y2:Y(y),stroke:'#34435b'});node('text',{x:60,y:Y(y)+5,'text-anchor':'end'},String(Number(y.toFixed(2))));node('text',{x:X(radius),y:395,'text-anchor':'middle'},radius);}node('text',{x:400,y:425,'text-anchor':'middle'},'Radius (kpc)');node('text',{x:15,y:210,transform:'rotate(-90 15 210)','text-anchor':'middle'},'Circular speed (km/s)');for(const[key,color]of [['diskSpeedKms','#f4c35b'],['haloSpeedKms','#60b5ff'],['totalSpeedKms','#ffffff']]){const p=node('polyline',{points:rows.map(r=>X(r.radiusKpc)+','+Y(r[key])).join(' '),fill:'none',stroke:color,'stroke-width':3,'data-component':key});p.dataset.values=JSON.stringify(rows.map(r=>[r.radiusKpc,r[key]]));}const current=RotationCore.model(state.radius,state);node('line',{x1:X(state.radius),x2:X(state.radius),y1:50,y2:370,stroke:'#c0c8d8','stroke-dasharray':'4 4'});node('circle',{cx:X(state.radius),cy:Y(current.totalSpeedKms),r:5,fill:'#ffffff'});document.getElementById('readout').textContent=`At ${state.radius} kpc: disk ${current.diskSpeedKms.toFixed(2)} km/s; halo ${current.haloSpeedKms.toFixed(2)} km/s; combined ${current.totalSpeedKms.toFixed(2)} km/s. Enclosed halo mass ${(current.haloEnclosedMassSolar/1e10).toFixed(3)} × 10¹⁰ solar masses. Squared component speeds add.`;let weightedMismatch=0;for(const d of sampleData){const predicted=RotationCore.model(d.radiusKpc,state).totalSpeedKms;weightedMismatch+=((d.speedKms-predicted)/d.sigmaKms)**2;node('line',{x1:X(d.radiusKpc),x2:X(d.radiusKpc),y1:Y(d.speedKms-d.sigmaKms),y2:Y(d.speedKms+d.sigmaKms),stroke:'#e58af6','stroke-width':2,'data-comparison-error':d.radiusKpc});node('circle',{cx:X(d.radiusKpc),cy:Y(d.speedKms),r:3,fill:'#e58af6','data-synthetic-observation':d.radiusKpc});}document.getElementById('readout').textContent+=` Weighted squared mismatch to the fixed synthetic sample: ${weightedMismatch.toFixed(3)} (dimensionless).`;window.RotationReview={comparison:sampleData,weightedMismatch,state:{...state},rows,current,maximum,plot:{left:70,width:660,bottom:370,height:320}};}
document.getElementById('reset').onclick=()=>{Object.assign(state,defaults);for(const[key,,, , ,gain]of controls)document.getElementById(key).value=state[key]/gain;render();};render();
let thickComparison=false;
document.getElementById('degeneracy').onclick=()=>{thickComparison=!thickComparison;Object.assign(state,defaults,thickComparison?{diskA:2.3,diskB:1}:{});for(const[key,,,,,gain]of controls)document.getElementById(key).value=state[key]/gain;render();document.getElementById('degeneracy-note').textContent=thickComparison?'Thicker disk: a = 2.3 kpc, b = 1 kpc. The comparison restores the fixed reference masses and halo. Its midplane rotation curve is exactly the same as a = 3 kpc, b = 0.3 kpc because a+b is unchanged. The three-dimensional mass density differs.':'Thinner reference disk: a = 3 kpc, b = 0.3 kpc. Both comparison states share a+b = 3.3 kpc and the same midplane rotation curve.';};
const originalReset=document.getElementById('reset').onclick;document.getElementById('reset').onclick=()=>{thickComparison=false;document.getElementById('degeneracy-note').textContent='';originalReset();};
for(const[key]of controls){const input=document.getElementById(key),original=input.onchange;input.onchange=()=>{original();document.getElementById('degeneracy-note').textContent='';};}
